        rolled = daily[col_key].rolling(7).mean().dropna()
        if len(rolled) >= 2:
            first_v = float(rolled.iloc[0])
            last_v = float(rolled.iloc[-1])
            pct = float((last_v - first_v) / first_v * 100) if first_v != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
