        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min() + 1
        s_t = np.log1p(s + shift) if abs(skew) > 2 else s
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_ext = q1 - 3 * iqr
        hi_ext = q3 + 3 * iqr
        flagged = s_t[(s_t < lo_ext) | (s_t > hi_ext)]
        if len(flagged) / len(s_t) > 0.05:
            anomalies_out.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"heavy-tailed distribution",
                "severity": "low",
